M.checkAll=async function({paperId=null,onlyAbnormal=false,includeHealthy=false,concurrency=2,onProgress=()=>{}}={}){
 if(M.running)throw Error('已有图片检测正在执行');M.running=true;M.cancel=false;M.controller=new AbortController();
 const all=M.scan().filter(m=>(!paperId||m.refs.some(r=>r.paperId===paperId))&&(onlyAbnormal?['failed','timeout','http403','http404','nonimage','candidate'].includes(m.status):(includeHealthy||!['ok','recovered'].includes(m.status))));
 let current=0;const results=[];let cursor=0;
 try{
  const workers=Array.from({length:Math.min(concurrency,all.length)},async()=>{
   while(cursor<all.length&&!M.cancel){const item=all[cursor++];let check;try{check=await M.detectOne(item.url,{signal:M.controller.signal});}catch(e){if(e.name==='AbortError')break;throw e;}results.push({url:item.url,...check});current++;onProgress({current,total:all.length,check,item});}
  });await Promise.all(workers);await S.saveMediaAudit();return {done:current,total:all.length,results,stopped:M.cancel};
 }finally{M.running=false;M.cancel=false;M.controller=null;}
};
M.stop=({releaseIndex=false}={})=>{M.cancel=true;M.controller?.abort();if(releaseIndex){M.lastIndex=null;M.cacheBank=null;}};
M.importCandidates=async function(file){
 if(!file||file.size>8*1024*1024)throw Error('候选清单过大，请分批导入');
 const data=JSON.parse((await file.text()).replace(/^\uFEFF/,''));
 const list=Array.isArray(data)?data:data.candidates;
 if(!Array.isArray(list))throw Error('请提供JSON数组或 candidates 数组');
 let added=0,ignored=0;
 const store=db();
 for(const x of list){
  const old=canonical(x.oldUrl),next=canonical(x.newUrl);
  if(!old||!next||old===next||!M.findUrlRefs(old).length){ignored++;continue;}
  if(store.candidates.some(c=>c.oldUrl===old&&c.newUrl===next)){ignored++;continue;}
  store.candidates.push({oldUrl:old,newUrl:next,evidence:String(x.evidence||'').slice(0,500),source:String(x.source||'本地候选清单').slice(0,180),verified:'unverified',createdAt:iso()});added++;
 }
 store.candidates=store.candidates.slice(-2000);await S.save();return {added,ignored};
};

M.findUrlRefs=url=>M.scan().find(x=>x.url===canonical(url))?.refs||[];
M.toReport=()=>({format:'jiangsu-media-audit-v1',generatedAt:iso(),summary:M.summary,store:S.storageMode(),entries:M.scan().map(m=>({mediaId:m.mediaId,url:m.url,kind:m.kind,status:M.statusName(db().checks[m.url]?.status||'unchecked'),detail:db().checks[m.url]||null,refs:m.refs})),inconsistentMaterials:M.materialInconsistencies});
