 for(const item of M.scan()){const c=db().checks[item.url]||{};for(const r of item.refs)for(const qid of r.questionIds)lines.push([item.mediaId,item.url,M.statusName(c.status||'unchecked'),r.paperId,qid,r.materialId||'',r.field,r.optionIndex??'',r.questionNo,c.reason||'']);}
 S.download('图片检测明细.csv','\uFEFF'+lines.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),'text/csv;charset=utf-8');
