    this.canvas.setAttribute('aria-label','手写草稿层');
    this.canvas.style.position='absolute';this.canvas.style.inset='0';this.canvas.style.width='100%';this.canvas.style.height='100%';
    this.canvas.style.pointerEvents='none';this.canvas.style.background='transparent';
    parent.style.position=parent.style.position||'relative';
    parent.appendChild(this.canvas);
    this.ctx=this.canvas.getContext('2d',{alpha:true});
