  _paintCurrent(){this.inkFrame=0;if(!this.current||this.current.brush==='erase')return;const ctx=this._live();ctx.clearRect(0,0,this.lastWidth,this.lastHeight);S.drawInkStroke(ctx,this.current,this.lastWidth,this.lastHeight);this.lastInkPaint=performance.now();}
  _erase(a,b){const ctx=this.ctx;ctx.save();ctx.globalCompositeOperation='destination-out';ctx.lineWidth=19;ctx.lineCap=ctx.lineJoin='round';ctx.beginPath();if(!a){ctx.arc(b.x*this.lastWidth,b.y*this.lastHeight,9.5,0,Math.PI*2);ctx.fill();}else{ctx.moveTo(a.x*this.lastWidth,a.y*this.lastHeight);ctx.lineTo(b.x*this.lastWidth,b.y*this.lastHeight);ctx.stroke();}ctx.restore();}
  _append(e){const p=this._point(e),stamp=Number(e.timeStamp);if(Number.isFinite(stamp)&&stamp>0){const key=stamp+':'+p.x+':'+p.y;if(stamp<this.lastSampleTime||this.sampleKeys.has(key))return;this.lastSampleTime=stamp;this.sampleKeys.add(key);}p.eventTime=Number.isFinite(stamp)?stamp:null;const last=this.current.points.at(-1);if(last&&Math.abs(last.x-p.x)<1e-8&&Math.abs(last.y-p.y)<1e-8)return;this.current.points.push(p);if(this.current.brush==='erase')this._erase(last,p);}
