  setMode(editable,tool='pen',width=1.7,visible=true){const nextTool=tool==='erase'?'erase':'pen',changed=this.active!==!!editable||this.visible!==!!visible;if(!editable||nextTool!==this.tool)this.finish();this.active=!!editable;this.visible=!!visible;if(this.active&&(this.lastWidth<=1||this.lastHeight<=1))this._resize();this.tool=nextTool;this.width=Number(width)||1.7;this.canvas.style.pointerEvents=this.active&&!this.readOnly?'auto':'none';this.canvas.style.touchAction=this.active&&!this.readOnly?'none':'pan-y';this.canvas.style.visibility=this.visible?'visible':'hidden';if(this.live)this.live.style.visibility=this.visible?'visible':'hidden';if(S.exam)this.examActive(S.exam);if(changed)this.paint();}
  examActive(exam){if(exam?.toolIndex!==undefined&&exam.toolIndex===Number(this.parent.closest('[data-question]')?.dataset.question))S.exam.lastInk=this;}
  _history(){S.inkEditHistory=S.inkEditHistory||new WeakMap();if(!S.inkEditHistory.has(this.note))S.inkEditHistory.set(this.note,{undo:[],redo:[]});return S.inkEditHistory.get(this.note);}
  undo(){if(this.readOnly)return;this.finish();const h=this._history(),entry=h.undo.pop();if(entry){if(entry.kind==='clear')this.note.strokes=entry.strokes.slice();else{const i=this.note.strokes.lastIndexOf(entry.stroke);if(i>=0)this.note.strokes.splice(i,1);this.note.redo.push(entry.stroke);}h.redo.push(entry);}else{if(!this.note.strokes.length)return;const stroke=this.note.strokes.pop();this.note.redo.push(stroke);h.redo.push({kind:'stroke',stroke});}this.note.undoCount=(this.note.undoCount||0)+1;S.recordInkEvent?.(this,'undo');this.onChange();this.paint();}
  redo(){if(this.readOnly)return;this.finish();const h=this._history(),entry=h.redo.pop();if(entry){if(entry.kind==='clear')this.note.strokes=[];else{this.note.strokes.push(entry.stroke);const i=this.note.redo.lastIndexOf(entry.stroke);if(i>=0)this.note.redo.splice(i,1);}h.undo.push(entry);}else{if(!this.note.redo.length)return;const stroke=this.note.redo.pop();this.note.strokes.push(stroke);h.undo.push({kind:'stroke',stroke});}this.note.redoCount=(this.note.redoCount||0)+1;S.recordInkEvent?.(this,'redo');this.onChange();this.paint();}
