  const safe=(exact?questions.slice():S.ensureGroupIntegrity(questions)).map(q=>S.presentQuestion?S.presentQuestion(q):q);
  if(!safe.length){S.toast('当前条件下没有可用题目。');return;}
  if(S.exam)S.exam.dispose();
