      questionId:q.id,recordId:q.id,sourceQuestionId:q.questionId||q.externalId||q.id,canonicalId:canonicalOf(q),
      paperId:q.paperId||null,paperOrder:q.paperOrder||q.order||null,paperTitle:q.paperTitle||q.source||null,
      subject:q.subject||'未分类',path:Array.isArray(q.path)?q.path.slice():[],tags:Array.isArray(q.tags)?q.tags.slice():[],
      year:q.year||null,type:q.type||q.path?.at(-1)||'',source:q.source||'',
      stemHtml:q.stemHtml||'',optionsHtml:Array.isArray(q.optionsHtml)?q.optionsHtml.slice():[],
      materialKey:q.materialKey||null,materialHtml:q.materialHtml||'',answer:q.answer||null,answerConflict:!!q.answerConflict,
      explanationHtml:q.explanationHtml||'',rate:q.rate??null,rateSource:q.rateSource||null
