S.commitImport=async function(preview){
  if(!preview?.candidate)throw Error('没有可提交的导入预览');
  const validCount=preview.candidate.bank.length-S.state.bank.length;
  if(!validCount&&!preview.stats?.existingQuestions&&!preview.audit)return {committed:0};
  if(preview.audit){preview.candidate.meta.importRecords=[...(S.state.meta.importRecords||[]).filter(b=>b.id!==preview.audit.id),{...preview.audit,committedAt:Date.now()}];}
  await S.persistState(preview.candidate);
  S.state=preview.candidate;S.reindex();
  return {committed:validCount,stats:preview.stats,issues:preview.issues};
};

S.importBank=async function(file,onProgress=()=>{}){
  const preview=await S.prepareImportFiles([file],onProgress);
  await S.commitImport(preview);
  return {added:preview.stats.newQuestions,crossPaper:preview.stats.crossPaper,existing:preview.stats.existingQuestions,issues:preview.issues,invalid:preview.stats.invalid};
};

S.chooseImport=function(options={}){
  const importOptions=['mock','real'].includes(options?.sourceKind)?{sourceKind:options.sourceKind}:{};
  const f=document.createElement('input');f.type='file';f.accept='.json,.txt';f.multiple=true;
  f.onchange=async()=>{
    const files=[...f.files];if(!files.length)return;
    try{
      const preview=await S.prepareImportFiles(files,(p,stage,detail)=>S.importProgressUpdate(p,stage,detail),importOptions);
      S.importProgressClose();
      const st=preview.stats,issueText=preview.issues.slice(0,12).map(x=>`<li>${E(x.file||'文件')}${x.row?` · 第${x.row}条`:''}：${E(x.message)}</li>`).join('');
      S.modal({
        title:'导入前核验结果',
        subtitle:`${files.length} 个文件 · 还没有写入本地数据库`,
        body:`<div class="import-preview-grid"><div><strong>${st.newQuestions}</strong><span>新增题目</span></div><div><strong>${st.crossPaper}</strong><span>同题跨卷</span></div><div><strong>${st.suspectedDuplicates}</strong><span>疑似重复</span></div><div><strong>${st.invalid}</strong><span>异常记录</span></div></div>
          <p class="dialog-copy">正常题会进入正式题库；异常记录只进入本次核验清单，不会阻塞其他题。已有题库不会在确认前发生任何修改。</p>
          ${issueText?`<details open><summary>异常/警告（显示前12条）</summary><ul class="import-issues">${issueText}</ul></details>`:'<p class="ok-note">未发现结构性异常。</p>'}`,
        footer:`<button class="button" data-close-modal>取消</button><button class="button primary" id="import-confirm">确认导入有效题目</button>`,
        onOpen:host=>{
          S.$('[data-close-modal]',host).onclick=S.closeModal;
          S.$('#import-confirm',host).onclick=async()=>{
            const b=S.$('#import-confirm',host);b.disabled=true;b.textContent='正在安全写入…';
            try{await S.commitImport(preview);S.closeModal();S.go('bank');S.toast(`导入完成：新增 ${st.newQuestions}，同题跨卷 ${st.crossPaper}，异常 ${st.invalid}`);}
            catch(e){b.disabled=false;b.textContent='确认导入有效题目';S.toast('导入未写入：'+e.message);}
          };
        }
      });
    }catch(e){S.importProgressClose();S.toast('导入检查失败：'+e.message);}
  };
  f.click();
};
