 await api('/api/account/logout',{});C.user=null;profile=null;C.verified=false;C.profileReady=false;C.recoveredOwner=null;S.state.meta.syncCachedUser=null;S.state.meta.syncLoggedOut=true;await S.saveHot({learningChange:false});
