  S.deletingRecords=true;
  const previous={sessions:S.state.sessions,attempts:S.state.attempts,aiReviews:S.state.aiReviews,lastSessionId:S.state.lastSessionId,learning:S.state.learning,meta:S.state.meta};
  S.state.meta={...previous.meta,deletedSessions:{...previous.meta.deletedSessions,[id]:Date.now()},syncConflicts:(previous.meta.syncConflicts||[]).filter(c=>!(c.path?.[0]==='sessions'&&c.path[1]===id))};
  S.state.sessions=previous.sessions.filter(s=>s.id!==id);S.state.attempts=previous.attempts.filter(a=>a.sessionId!==id);S.state.aiReviews=previous.aiReviews.filter(a=>a.sessionId!==id);
  S.state.learning={...previous.learning,reviewState:{},canonicalStats:{}};
  if(S.state.lastSessionId===id)S.state.lastSessionId=null;S.rebuildLearningStats();
  try{await S.saveHot();if(S.route==='history')S.renderHistory();S.toast('记录已删除');
   scheduleDeletionSync();
  }catch(e){Object.assign(S.state,previous);S.toast('删除未保存，请重试：'+e.message);}
  finally{S.deletingRecords=false;}
