S.openBirthday=function(){if(!H.birthday().available||birthdayOverlay)return;audio.stop();birthdayReturnFocus=document.activeElement;birthdayOverlay=document.createElement('section');birthdayOverlay.className='birthday-overlay';birthdayOverlay.setAttribute('role','dialog');birthdayOverlay.setAttribute('aria-modal','true');birthdayOverlay.setAttribute('aria-label','生日来信');birthdayOverlay.innerHTML='<button class="birthday-close" aria-label="关闭生日来信">返回学习</button><iframe title="给娜宝的一封生日来信" src="birthday.html" sandbox="allow-scripts allow-same-origin"></iframe>';document.body.append(birthdayOverlay);document.body.style.overflow='hidden';birthdayOverlay.querySelector('button').onclick=closeBirthday;birthdayOverlay.querySelector('button').focus();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeBirthday();closePops();}if(e.key==='Tab'&&birthdayOverlay&&document.activeElement===birthdayOverlay.querySelector('button')&&e.shiftKey){e.preventDefault();birthdayOverlay.querySelector('iframe').focus();}});
S.closeHomePops=closePops;
function closePops(){for(const id of ['theme','sound']){const pop=S.$('#home-'+id+'-pop');if(pop)pop.hidden=true;}S.$$('[data-home-pop]').forEach(b=>b.setAttribute('aria-expanded','false'));}
