 S.$$('[data-theme]').forEach(b=>b.onclick=()=>{theme=b.dataset.theme;put('theme',theme);decorate();const scene=S.homeScenes[({a:'blue',b:'mono',c:'meadow'})[theme]+'-'+H.period()],hero=S.$('.home-hero');if(hero){hero.style.background=scene.background;S.$('.landscape',hero).innerHTML=scene.svg;}S.$$('[data-theme]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.theme===theme)));closePops();});
