 if(f&&typeof f.excludeFromLearning==='boolean'&&f.inclusionOverride!==false)return f;
 return {userCause:'',exclusionReason:'',...f,excludeFromLearning:!S.reviewDefaultIncluded(s,qid),inclusionOverride:false};
