 for(const q of s.questions)if(includeAll||feedback[q.id]?.inclusionOverride===false)feedback[q.id]=S.reviewFeedbackFor(s,q.id);
 if(S.SyncModel.stable(feedback)===S.SyncModel.stable(s.reviewFeedback||{}))return;
