S.reviewReady=s=>s?.reviewCompletion?.status==='confirmed'&&s.reviewCompletion.revision===(s.reviewRevision||0)&&s.reviewCompletion.feedbackSignature===S.SyncModel.stable(s.reviewFeedback||{});
